import type { Player } from './index';

export const squad: Player[] = [
  // Porteros
  { number: 1, name: 'Melvin Mastil', position: 'GK', age: 0, club: 'Lausanne-Sport', bio: {"es":"La mayoría de los aficionados argelinos saben muy poco sobre Mastil, nacido en Francia, que fue convocado sólo unos meses antes del Mundial, pero que es aficionado de los Fennecs desde hace mucho tiempo. Mastil, que se clasifica para Argelia gracias a su abuelo, dijo a L'Équipe: \"Crecí apoyando a la selección argelina. Cuando los vi en el Mundial de 2014 y en la Copa Africana de Naciones de 2019, me hizo soñar\". Ahora tiene la oportunidad de construir un futuro a largo plazo con el país de su abuelo. El jugador de 26 años ha desarrollado toda su carrera profesional en Suiza y recientemente estuvo cedido en segunda división con el Stade Nyonnais. Ahora que Argelia necesita una renovación en el departamento de porteros, Mastil tiene un perfil intrigante, mide 1,93 my es el capitán de su club. Su techo potencial parece más alto que el de otros porteros argelinos en Europa, lo que lo convierte en un fuerte candidato para actuar como portero suplente por ahora.","en":"Most Algeria fans know very little about French-born Mastil, who was only called up a few months before the World Cup, but he has long been a fan of the Fennecs. Mastil, who qualifies for Algeria through a grandfather, told L'Équipe: “I grew up supporting the Algerian national team. When I saw them at the 2014 World Cup and the 2019 Africa Cup of Nations, it made me dream.” Now he has the chance to build a long-term future with his grandad’s country. The 26-year-old has spent his entire professional career in Switzerland and has most recently been on loan in the second division with Stade Nyonnais. With Algeria in need of a refresh in the goalkeeping department, Mastil cuts an intriguing profile, standing at 1.93m and captaining his club. His potential ceiling appears higher than that of other Algerian goalkeepers in Europe, making him a strong candidate to serve as a reserve keeper for now."} },
  { number: 16, name: 'Oussama Benbot', position: 'GK', age: 31, club: 'USM Alger', bio: {"es":"Benbot comenzó la Copa Africana de Naciones 2025 como portero suplente de Argelia, y su torneo terminó en una improbable decepción. Después de que los Fennecs ganaran sus dos primeros partidos de la fase de grupos, el entrenador Vladimir Petkovic rotó a gran parte de su equipo para el último partido del grupo contra Guinea Ecuatorial. Benbot, sin embargo, permaneció en el banquillo cuando el tercer portero Anthony Mandrea recibió el visto bueno. Frustrado por la decisión, el jugador del USM Alger anunció su retirada internacional en un comunicado en Instagram tras el torneo. Su ausencia, sin embargo, duró poco. Las lesiones de Luca Zidane y Melvin Mastil llevaron a la Federación Argelina de Fútbol a tender la mano y dejar claro que seguían contando con él. Benbot, que tuvo una excelente temporada con el USM Argel y ayudó al club a ganar la Copa Confederación Caf contra el Zamalek, aceptó regresar. \"Quizás tomé la decisión [de retirarme] demasiado rápido. Tuve una conversación con el presidente de la federación para explicarle mi situación y lo que tenía en mente. Agradezco al presidente de la federación porque encontramos puntos en común y entendió mi posición\", dijo.","en":"Benbot started the 2025 Africa Cup of Nations as Algeria's backup goalkeeper, and his tournament ended in unlikely disappointment. After the Fennecs won their opening two group-stage matches, coach Vladimir Petkovic rotated much of his squad for the final group game against Equatorial Guinea. Benbot, however, remained on the bench as third-choice goalkeeper Anthony Mandrea was given the nod. Frustrated by the decision, the USM Alger player announced his international retirement in a statement on Instagram after the tournament. His absence, however, proved short-lived. Injuries to Luca Zidane and Melvin Mastil prompted the Algerian Football Federation to reach out and make clear that they still counted on him. Benbot, who had an outstanding season with USM Algiers and helped the club win the Caf Confederation Cup against Zamalek, agreed to return. \"Perhaps I made the decision [to retire] too quickly. I had a discussion with the president of the federation to explain my situation and what was on my mind. I thank the president of the federation because we found common ground and he understood my position,\" he said."} },
  { number: 23, name: 'Luca Zidane', position: 'GK', age: 28, club: 'Granada', bio: {"es":"“Si lo convoqué es porque se lo merece”, dijo Vladimir Petkovic a la prensa argelina después de que la primera aparición de Luca Zidane en la selección nacional el año pasado causara sorpresa, y el técnico negó que el famoso padre del joven portero hubiera influido en su decisión. Durante la Copa Africana de Naciones, Zinedine padre asistió a tres partidos de Argelia para apoyar a su hijo y, por momentos, pareció eclipsar las impresionantes actuaciones de Luca en la portería. El portero del Granada, que jugó en varias categorías inferiores de Francia antes de fichar por Argelia, no es el número 1 más alto con 1,83 m, pero es un buen comunicador y su distribución es excelente, lo que permite al equipo jugar desde atrás con compostura. Cada vez que hace una parada, los aficionados argelinos corean \"Zizou, Zizou, Zizou\".","en":"“If I called him up, it’s because he deserves it,” Vladimir Petkovic told the Algerian press after a few eyebrows were raised by Luca Zidane’s first appearance in the national squad last year, the manager denying that the young keeper’s famous dad had influenced his decision. During the Africa Cup of Nations, Zinedine senior attended three of Algeria’s matches to support his son and, at times, it did feel like he overshadowed Luca’s impressive performances in goal. The Granada keeper, who played for France at various youth levels before declaring for Algeria, isn’t the tallest No1 at 1.83m, but he is a good communicator, and his distribution is excellent, which allows the side to play out from the back with composure. Whenever he makes a save, Algerian fans chant “Zizou, Zizou, Zizou.”"} },
  // Defensores
  { number: 2, name: 'Aissa Mandi', position: 'DF', age: 35, club: 'Lille', captain: true, bio: {"es":"Este consumado profesional, con más partidos internacionales que cualquier otro argelino, superó la marca de 100 en 2024. Quizás su ex entrenador con la selección nacional, Djamel Belmadi, lo describió mejor cuando dijo: \"Aissa tiene habilidades naturales de liderazgo y un impacto significativo en los jugadores, tanto en los partidos como en los entrenamientos. Es una buena persona y una presencia positiva dentro del grupo. Incluso su falta de velocidad, la compensa con inteligencia y buen juicio a la hora de tomar la iniciativa\". Mandi es uno de los dos veteranos de este equipo, junto con Riyad Mahrez, quien también estuvo en el equipo de la Copa del Mundo de 2014 que llevó a Alemania al límite en los octavos de final. Tiene un papel importante que desempeñar este verano, dentro o fuera de la cancha, siendo una presencia tranquilizadora y autoritaria para los defensores más jóvenes. Cuando Argelia se clasificó para este verano, escribió en línea: \"Desde el 29 de marzo de 2022 sólo tenemos una cosa en la cabeza: devolver a Argelia a donde pertenece: al Mundial. Orgullo y determinación para lo que viene\".","en":"The consummate professional, with more international caps than any other Algerian, having passed the 100 mark back in 2024. Perhaps his former coach with the national team, Djamel Belmadi, described him best when he said: “Aissa has natural leadership skills and a significant impact on the players, both in matches and in training. He’s a good person and a positive presence within the group. Even his lack of speed, he compensates for with intelligence and sound judgment when it comes to taking initiative.” Mandi is one of two veterans in this squad, alongside Riyad Mahrez, who was also in the 2014 World Cup squad that pushed Germany to its limit in the Last 16. He has a big role to play this summer, on the pitch or off it, in being a calming, authoritative presence for the younger defenders. When Algeria qualified for this summer he wrote online: “Since 29 March 2022 only one thing has been on our minds: bringing Algeria back where it belongs: to the World Cup. Pride and determination for what comes next.\""}, special: "Proud veteran" },
  { number: 3, name: 'Achraf Abada', position: 'DF', age: 0, club: 'USM Alger', bio: {"es":"Abada, un verdadero tardío, hizo su avance internacional a la edad de 26 años. Durante gran parte de su carrera, el central pasó desapercibido, jugando en Argelia para MC El Eulma y ASO Chlef, pero realmente llamó la atención con sus actuaciones en la Copa Árabe de la FIFA del año pasado en Qatar, impresionando con su velocidad, atletismo y agresión implacable. En enero firmó con el USM Alger en un lucrativo acuerdo a largo plazo, con el acuerdo incluyendo una gran cláusula de venta y otra cláusula supuestamente estipulando que su nuevo club financiaría el campo de entrenamiento de pretemporada de su antiguo club este verano si Abada llegaba al equipo de la Copa del Mundo. Entonces, buenas noticias para ASO Chlef. Todavía hay aspectos que mejorar en lo que respecta al juego con el balón en los pies, pero su instinto defensivo por sí solo le valió su convocatoria este verano.","en":"A real late bloomer, Abada made his international breakthrough at the age of 26. For much of his career the centre-back went under the radar, playing in Algeria for MC El Eulma and ASO Chlef, but he really turned heads with his displays at last year’s Fifa Arab Cup in Qatar, impressing with his speed, athleticism and relentless aggression. In January he signed for USM Alger on a lucrative long-term deal, with the deal featuring a big sell-on clause and another clause reportedly stipulating that his new club would fund his old club’s pre-season training camp this summer if Abada made the World Cup squad. Good news for ASO Chlef, then. There are still areas for improvement when it comes to playing with the ball at his feet, but his defensive instincts alone earned him his call-up this summer."}, special: "Late bloomer" },
  { number: 4, name: 'Mohamed Tougai', position: 'DF', age: 26, club: 'Espérance de Tunis', bio: {"es":"Argelia no anunció su equipo para la Copa del Mundo hasta el 31 de mayo, mucho más tarde que la mayoría de las demás naciones participantes. Para entonces ya quedaban pocas sorpresas. Los periodistas apostados fuera del aeropuerto ya habían fotografiado y filmado a los jugadores que llegaban al campamento, armando gradualmente el equipo de Vladimir Petkovic antes del anuncio oficial. La excepción notable fue Tougai. El defensa había regresado a Argelia varias semanas antes procedente de Túnez, donde su club sufrió una campaña decepcionante y no logró ganar el título de liga por segunda vez en la última década. Su inclusión llamó la atención, sobre todo porque Petkovic ha seleccionado a seis centrales para el torneo. Entre ellos, Tougai es posiblemente el menos versátil. Un defensor tradicional y sensato, prioriza ganar duelos físicos y despejar el peligro antes que construir ataques o realizar pases rompedores en el medio campo.","en":"Algeria did not announce their World Cup squad until 31 May, significantly later than most of the other participating nations. By then, there were few surprises left. Journalists stationed outside the airport had already photographed and filmed players arriving for camp, gradually piecing together Vladimir Petkovic's squad before the official announcement. The notable exception was Tougai. The defender had returned to Algeria several weeks earlier from Tunisia, where his club endured a disappointing campaign and failed to win the league title for only the second time in the past decade. His inclusion raised eyebrows, particularly as Petkovic has selected six centre-backs for the tournament. Among them, Tougai is arguably the least versatile. A traditional, no-nonsense defender, he prioritises winning physical duels and clearing danger over building attacks or playing line-breaking passes through midfield."}, special: "Surprise call-up" },
  { number: 5, name: 'Zineddine Belaid', position: 'DF', age: 27, club: 'JS Kabylie', bio: {"es":"Un central fiable, aunque poco espectacular. El mayor logro de Belaid llegó en 2023, cuando capitaneó al USM Alger y ganó el título de la Copa Confederación CAF. Siguió un breve paso por Bélgica con el Sint-Truiden, antes de regresar con mucho dinero al club más condecorado de Argelia, el JS Kabylie, el año pasado. Es poco probable que Belaid sea titular en los partidos, pero es capaz de ocupar un lugar en la defensa cuando Argelia necesita proteger una ventaja, particularmente contra amenazas aéreas. En la Copa Africana de Naciones de 2025 participó en tres apariciones y marcó un gol de cabeza en un córner contra Guinea Ecuatorial, que luego dedicó a su difunto padre, escribiendo en línea: \"Mi primer gol con la selección nacional, en el escenario más grande de África. Sentí tu presencia conmigo, papá. Este gol está dedicado a ti, a mi familia, al cuerpo técnico que creyó en mí y a la maravillosa afición argelina\".","en":"A reliable, if unspectacular, centre-back. Belaid’s greatest achievement came in 2023 when he captained USM Alger to a CAF Confederation Cup title. A brief stint in Belgium with Sint-Truiden followed, before a big-money return to Algeria’s most decorated club, JS Kabylie last year. Belaid is unlikely to start matches, but he is capable of slotting into defence when Algeria need to protect a lead, particularly against aerial threats. At the 2025 Africa Cup of Nations he made three appearances and scored a headed goal from a corner against Equatorial Guinea, which he then dedicated to his late father, writing online: \"My first goal with the national team, on Africa's biggest stage. I felt your presence with me, dad. This goal is dedicated to you, to my family, to the coaching staff who believed in me, and to the wonderful Algerian supporters.”"} },
  { number: 13, name: 'Jaouen Hadjam', position: 'DF', age: 23, club: 'Young Boys', bio: {"es":"Si no fuera por el talento excepcional de Rayan Aït-Nouri, Hadjam sería el lateral izquierdo titular de Argelia. Producto de los famosos banlieues parisinos, Hadjam combina la seguridad técnica que desarrolló cuando era joven con una confiabilidad defensiva madura. Su calidad con el balón le permite también hacer un trabajo como lateral derecho zurdo; para que él y Aït-Nouri pudieran trabajar en la misma formación. Pero entrar en el once inicial sigue siendo una tarea ardua dada la competencia que tiene por delante. Los informes del invierno pasado sugirieron que Besiktas había llegado a un acuerdo con Young Boys para su transferencia, solo para que el movimiento colapsara después de que el jugador no logró llegar a un acuerdo personal con el lado turco. Estuvo en el centro de una disputa en 2023 cuando su entrenador en Nantes, Antoine Kombouaré, lo dejó fuera de un partido de la Ligue 1 porque se negó a romper su ayuno durante el Ramadán. Kombouaré insistió: \"No es un castigo. No es una controversia. Yo apoyo a los que ayunan, pero en los días de partido no se debe ayunar. Yo pongo las reglas\".","en":"Were it not for the exceptional talent of Rayan Aït-Nouri, Hadjam would be Algeria’s first-choice left-back. A product of the famed Parisian banlieues, Hadjam combines the technical assurance he developed as a youngster with mature defensive reliability. His quality on the ball means he can also do a job as a left-footed right-back; so he and Aït-Nouri could work in the same line-up. But breaking into the starting XI remains an uphill task given the competition ahead of him. Reports last winter suggested that Besiktas had reached an agreement with Young Boys for his transfer, only for the move to collapse after the player failed to agree personal terms with the Turkish side. He was at the centre of a row in 2023 when his coach at Nantes, Antoine Kombouaré, dropped him for a Ligue 1 match because he refused to break his fast during Ramadan. Kombouaré insisted: “It’s not a punishment. It’s not a controversy. I support those who fast, but on matchdays, you should not fast. I set the rules.”"} },
  { number: 15, name: 'Rayan Aït-Nouri', position: 'DF', age: 25, club: 'Manchester City', bio: {"es":"Hay que ser valiente para abalanzarse sobre Rayan Aït-Nouri cuando tiene el balón en los pies. No es exagerado describir al lateral nacido en Francia como uno de los mejores defensores regateadores del fútbol mundial, un defensor que parece cómodo sin esfuerzo llevando el balón hasta el último tercio y convirtiendo secuencias defensivas en secuencias de ataque. Tomó la decisión de representar a Argelia en 2023 y dijo: \"Argelia son mis raíces... Cuando estoy en Argelia, siempre estoy feliz; mi estado de ánimo cambia tan pronto como llego allí. La gente sonríe, es amigable, todos tienen las manos en el corazón; es magnífico\". Con la selección nacional su forma no siempre ha sido tan buena como a nivel de clubes, con actuaciones mixtas en la Copa Africana de Naciones del año pasado, pero su forma previa a la Copa del Mundo en el City (al que llegó procedente de los Wolves por £31 millones el año pasado) fue alentadoramente fuerte. Debería ser una gran ventaja este verano.","en":"You have to be brave to lunge in on Rayan Aït-Nouri when he has the ball at his feet. It’s no exaggeration to describe the France-born full-back as one of the best dribbling defenders in world football, a defender who looks effortlessly comfortable carrying the ball into the final third and turning defensive sequences into attacking ones. He made the decision to represent Algeria in 2023, saying: “Algeria is my roots … When I’m in Algeria, I’m always happy; my mood changes as soon as I arrive there. The people are smiling, they’re friendly, everyone has their hands on their heart; it’s magnificent.” With the national side his form has not always been as strong as it has at club level, with mixed displays at last year’s Africa Cup of Nations, but his pre-World Cup form at City – whom he joined from Wolves for £31m last year – was encouragingly strong. He should be a huge asset this summer."} },
  { number: 17, name: 'Rafik Belghali', position: 'DF', age: 23, club: 'Verona', bio: {"es":"Belghali estuvo peligrosamente cerca de perderse este torneo. Después de la eliminación de Argelia en cuartos de final de la Copa Africana de Naciones del año pasado contra Nigeria, se volvió viral por perseguir al árbitro por el túnel en Marrakech, desahogando su frustración con los árbitros. Dijo más tarde: \"Después del pitido final, me acerqué al árbitro para estrecharle la mano. Su reacción me sorprendió y, en el calor del momento, lo seguí brevemente para preguntarle por qué. No hubo agresión ni intención de confrontación. Reconozco, sin embargo, que dejé que la situación se prolongara más de lo debido\". Siguió una sanción pero, afortunadamente para el lateral nacido en París, la suspensión se limitó a las eliminatorias de la Afcon 2027. Durante el año pasado ha sido un activo clave tanto para Verona como para la selección nacional. Si bien puede quedar expuesto en la defensa uno a uno, su motor es implacable y avanza constantemente para brindar amplitud y superponerse a Riyad Mahrez, a quien le gusta moverse hacia adentro. Esa dinámica es una parte crucial de la estructura de ataque de Argelia.","en":"Belghali came dangerously close to missing this tournament. After Algeria’s quarter-final exit at last year’s Africa Cup of Nations against Nigeria, he went viral for chasing the referee down the tunnel in Marrakesh, venting his frustration at the officials. He said later: “After the final whistle, I approached the referee to shake his hand. His reaction surprised me and, in the heat of the moment, I briefly followed him to ask why. There was no aggression or intention of confrontation. I do acknowledge, however, that I let the situation drag on longer than it should have.” A ban followed but, fortunately for the Paris-born wing-back, the suspension was limited to 2027 Afcon qualifiers. Over the past year he has been a key asset for both Verona and the national team. While he can be exposed in one-on-one defending, his engine is relentless, constantly surging forward to provide width and overlap Riyad Mahrez, who likes to drift inside. That dynamic is a crucial part of Algeria’s attacking structure."} },
  { number: 21, name: 'Ramy Bensebaini', position: 'DF', age: 31, club: 'Borussia Dortmund', bio: {"es":"No muchos centrales tienen nuez moscada y acabados desconchados en sus carretes destacados, pero Bensebaini es uno de ellos. Habitual del Borussia Dortmund, es el defensor más destacado de Argelia. Dotado de un pie izquierdo en forma de varita, es fundamental para la preparación del juego de Argelia desde atrás. Más allá de su compostura con el balón, aporta intensidad, ritmo y presencia física, aunque puede ser propenso a sufrir fallos de concentración. Esa vulnerabilidad fue evidente este año en el play-off de la Liga de Campeones contra el Atalanta, donde cometió repetidas faltas antes de conceder un penalti y ser expulsado. Hace poco más de una década estuvo a prueba en el Arsenal, pero quedó en nada por culpa de los trámites. \"Pasé un tiempo allí, un mes a prueba, en 2015\", dijo Bensebaini a Ouest France en 2019. \"Estaba entrenando con el primer equipo y jugando partidos con el filial. Había hablado varias veces con Arsene Wenger. Al final, cinco entrenadores decidieron mi futuro. Cuatro de ellos me dieron el visto bueno y me habrían contratado, pero uno dijo que era imposible ficharme porque no tenía pasaporte europeo y no tenía suficiente internacional. gorras.\"","en":"Not many centre-halves have nutmegs and chipped finishes in their highlight reels, but Bensebaini is one of those. A regular for Borussia Dortmund, he is Algeria’s standout defender. Gifted with a wand-like left foot, he is central to Algeria’s build-up play from the back. Beyond his composure on the ball, he brings intensity, pace, and physical presence, although he can be prone to lapses in concentration. That vulnerability was evident this year in the Champions League play-off tie against Atalanta, where he was repeatedly at fault before conceding a penalty and being sent off. Just over a decade ago he was on trial at Arsenal, but it came to nothing, due to paperwork. \"I spent time there, a month on trial, in 2015,\" Bensebaini told Ouest France in 2019. \"I was training with the first team and I was playing matches with the reserves. I had spoken several times with Arsene Wenger. In the end, five coaches decided my future. Four of them gave me the thumbs up and would have taken me, but one of them said it was impossible to sign me, because I didn't have a European passport and didn't have enough international caps.\""} },
  { number: 26, name: 'Samir Chergui', position: 'DF', age: 27, club: 'Paris FC', bio: {"es":"Los aficionados argelinos no tardaron mucho en darse cuenta de lo que Chergui aportaría a la selección nacional cuando salió del banquillo en su debut el año pasado. Sin nervios ni dudas: solo una exhibición llena de acción que presenta una acalorada batalla con un oponente. Posteriormente, el portero Alexis Guendouz subtituló las imágenes en las redes sociales: “Chergui, mi soldado”. En un equipo caracterizado por su estilo técnico, botas de neón y peinados caros, Chergui es un defensor calvo y sencillo de la vieja escuela que simplemente sigue con su trabajo. Ha madurado desde sus inicios en Auxerre, donde fue liberado tras una serie de incidentes disciplinarios. Siguió trabajando y el Paris FC le dio una segunda oportunidad, y ha devuelto plenamente su confianza. Comparte sus historias con los jugadores más jóvenes del club. \"Les digo que aprecien la suerte que tienen de estar allí. Mi ejemplo debería servirles de lección\".","en":"It didn’t take Algeria fans long to work out what Chergui would bring to the national side when he came off the bench for his debut last year. No nerves, no hesitation - just an all-action display featuring a heated running battle with an opponent. Afterwards, goalkeeper Alexis Guendouz captioned footage on social media: “Chergui, my soldier.” In a squad characterised by technical flair, neon boots and expensive hairdos, Chergui is a balding old-school no-frills defender who just gets on with the job. He has matured since his early days at Auxerre where he was released after a series of disciplinary incidents. He kept working and was given a second chance by Paris FC, and has fully repaid their faith. He shares his stories with the club’s younger players. “I tell them to appreciate how lucky they are to be there. My example should serve as a lesson for them.\""} },
  // Volantes
  { number: 6, name: 'Ramiz Zerrouki', position: 'MF', age: 28, club: 'Feyenoord', bio: {"es":"En un equipo de jugadores de pelota con dedos centelleantes, Zerrouki corre contra la corriente. Formado en la academia del Ajax, domina los principios fundamentales del juego: siempre en la posición correcta en el momento correcto, con pases que tienden a ser seguros y horizontales. Proporciona un equilibrio a un equipo que puede ser impredecible, liberando a sus compañeros más progresistas. Se ha ganado la confianza de los sucesivos entrenadores de Argelia desde su debut en 2021, pero para un país que se enorgullece de su talento técnico, no es el favorito de los fanáticos y, a menudo, termina siendo el primer jugador en cargar con la peor parte de la culpa cuando las cosas van mal. Pasó la temporada pasada cedido por el Feyenoord en uno de sus antiguos clubes, el Twente, en un intento por asegurarse más tiempo de juego regular y su lugar en el equipo de este verano. Dio sus frutos.","en":"In a team of twinkle-toed ball-players, Zerrouki runs against the grain. Schooled in the Ajax academy, he has mastered the game’s fundamental principles: always in the right position at the right time, with his passes tending to be safe and horizontal. He provides a balance to a team that can be unpredictable, freeing up his more forward-thinking teammates. He has earned the trust of successive Algeria coaches since his debut in 2021, but for a country that prides itself on technical flair, he isn’t a fan favourite, and often ends up being the first player to take the brunt of the blame when things go wrong. He spent last season on loan from Feyenoord back at one of his former clubs, Twente, in a bid to secure more regular game time, and his spot in this summer’s squad. It paid off."} },
  { number: 8, name: 'Houssem Aouar', position: 'MF', age: 28, club: 'Al-Ittihad', bio: {"es":"Los fanáticos de la Premier League pueden reconocer el nombre de Aouar por los muchos rumores de transferencia en los que estuvo involucrado durante su último año en Lyon en 2023. Al final, ninguno de los movimientos salió bien y, en cambio, se unió a la Roma, luciendo sólido allí bajo José Mourinho en un sistema 3-5-2. Sin embargo, su estancia fue breve: al año siguiente se vio atraído por un traspaso de mucho dinero al Al-Ittihad, en el que su mentor, Karim Benzema, desempeñó un papel clave. Aouar, un ex internacional juvenil de Francia que nació en Lyon, cambió de alianza internacional en 2023 y dijo: \"Había estado rondando por mi cabeza durante un tiempo, pero no quería acercarme a Argelia porque tenía miedo de parecer un oportunista. Pero cuando el presidente me tendió la mano me pareció que estaba destinado a ser así. Significa mucho para mí. Sinceramente, después de elegir jugar para Francia, me arrepentí\". Con Argelia, su papel es moverse entre líneas, recibir en media vuelta y mover rápidamente el balón desde el centro del campo a los pies de los atacantes. No se sorprenda al verlo contribuir con uno o dos goles, llegando tarde al área.","en":"Premier League fans might recognise Aouar’s name from the many transfer rumours he was involved in during his final year at Lyon in 2023. In the end none of the moves came off, and instead he joined Roma, looking solid there under José Mourinho in a 3-5-2 system. His stay was brief, though: the following year he was drawn to a big-money move to Al-Ittihad, with his mentor, Karim Benzema, playing a key role in the move. Aouar, a former France youth international who was born in Lyon, switched international allegiances in 2023, saying: “It had been going through my head for a while, but I didn’t want to make an approach to Algeria myself because I was afraid of coming across as an opportunist. But when the president held his hand out to me it seemed like it was just meant to be. It means a lot to me. In all honesty, after choosing to play for France I regretted it.” With Algeria his role is to drift between the lines, receive on the half-turn, and quickly move the ball from midfield into the attackers’ feet. Don’t be surprised to see him chip in with a goal or two, either, arriving late into the box."} },
  { number: 10, name: 'Farès Chaïbi', position: 'MF', age: 23, club: 'Eintracht Frankfurt', bio: {"es":"Terraillon, en las afueras de Lyon, es probablemente más conocido por producir a Karim Benzema. Pero cuando visité el suburbio antes de la final de la Liga de Campeones de 2022, los lugareños querían hablar de un joven de Toulouse llamado Farès Chaïbi. \"Tiene el paquete completo y quiere jugar con Argelia\", me dijo un adolescente llamado Younes. Unos meses más tarde, Chaïbi ganó el premio al Novato del Año de la Ligue 1, reflejando sus ocho goles en 41 apariciones en todas las competiciones. Esa temporada de debut le valió el traslado al Eintracht Frankfurt, pero en Alemania ha tenido altibajos. Un mediocampista de hombros anchos capaz de jugar en la banda o por el medio en un papel de área a área, su lanzamiento de jugadas a balón parado desde las esquinas y los tiros libres lo hace particularmente valioso para Argelia; El equipo ha mejorado constantemente en ese aspecto con Vladimir Petkovic.","en":"Terraillon, on the outskirts of Lyon, is probably best known for producing Karim Benzema. But when I visited the suburb before the 2022 Champions League final, locals wanted to talk instead about a youngster at Toulouse named Farès Chaïbi. “He’s the full package and wants to play for Algeria,” a teenager named Younes told me. A few months later, Chaïbi won Ligue 1 Rookie of the Year, reflecting his eight goals in 41 appearances across all competitions. That debut season earned him a move to Eintracht Frankfurt, but in Germany he has blown hot and cold. A broad-shouldered midfielder capable of playing on the wing or through the middle in a box-to-box role, his set-piece delivery from corners and free-kicks makes him particularly valuable to Algeria; the side has steadily improved in that area under Vladimir Petkovic."}, special: "Set-piece specialist" },
  { number: 14, name: 'Hicham Boudaoui', position: 'MF', age: 26, club: 'Nice', bio: {"es":"Puede que Riyad Mahrez sea el nombre más famoso de Argelia e Ibrahim Maza su perspectiva más interesante, pero el jugador más indispensable de los Fennecs es sin duda Hicham Boudaoui. A Argelia no le faltan centrocampistas ofensivos ingeniosos que sepan driblar y anotar. Lo que a menudo le falta es un centrocampista capaz de cubrir tanto terreno como Boudaoui de forma constante. En un pasaje del juego, puedes ver al nativo de Béchar protegiendo la línea de fondo como un tradicional número 6, luego avanzando en un papel más de caja a caja para apoyar a sus extremos, e incluso desplazándose hacia el bolsillo del número 10. Habitualmente se sitúa entre los mejores corredores de la Ligue 1 en términos de distancia recorrida, con una media de entre 11 y 12 km por partido, y será incansable en el medio de Argelia este verano. Antes del torneo, lo vincularon con clubes como Brighton, Marsella y Galatasaray; Es probable que la lista de pretendientes crezca.","en":"Riyad Mahrez may be Algeria’s most famous name, and Ibrahim Maza its most exciting prospect, but the Fennecs’ most indispensable player is definitely Hicham Boudaoui. Algeria has no shortage of inventive attacking midfielders who can dribble and score. What it often lacks is a midfielder capable of covering as much ground as Boudaoui does on a consistent basis. In one passage of play, you can catch the Bechar native shielding the backline like a traditional No 6, then surging forward in a more box-to-box role to support his wingers, and even drifting into the No 10 pocket. He regularly ranks among the top runners in Ligue 1 in terms of distance covered, averaging between 11km and 12km per match, and will be tireless in the middle for Algeria this summer. He was being linked with clubs including Brighton, Marseille and Galatasaray before the tournament; the list of suitors is likely to grow."}, special: "Midfield powerhouse" },
  { number: 19, name: 'Nabil Bentaleb', position: 'MF', age: 0, club: 'Lille', bio: {"es":"Doce años después de su última aparición en la Copa del Mundo, la carrera de Bentaleb ha cerrado el círculo. En 2014, el centrocampista que entonces tenía 19 años era titular habitual en el Tottenham y acababa de impresionar en el Mundial, con un futuro aparentemente brillante por delante. Sin embargo, los problemas disciplinarios recurrentes interrumpieron varios períodos en clubes desde los Spurs hasta el Schalke, e incluso se encontró sin equipo durante la temporada 2020-21. Bentaleb reconstruyó poco a poco su carrera en Francia y regresó al club de su ciudad natal, el Lille, donde comenzó su andadura futbolística. Su mayor desafío en la vida llegó en junio de 2024 cuando sufrió un infarto durante un entrenamiento. Después de consultar con su ex compañero de equipo Christian Eriksen y recibir un marcapasos, logró regresar al Lille, se convirtió en capitán y realizó una de las mejores temporadas de su carrera. \"Nunca se soltó. Creía en sí mismo y creía en las personas que lo cuidaban\", dijo el entrenador del Lille, Bruno Genesio.","en":"Twelve years after his last World Cup appearance, Bentaleb's career has come full circle. In 2014, the then 19-year-old midfielder was a regular starter for Tottenham and had just impressed at the World Cup, with a seemingly bright future ahead of him. However, recurring disciplinary issues disrupted several spells at clubs from Spurs to Schalke, and he even found himself without a team during the 2020-21 season. Bentaleb gradually rebuilt his career in France, returning to his hometown club, Lille, where his football journey began. His greatest challenge in life came in June 2024 when he suffered a heart attack during training. After consulting with his former teammate Christian Eriksen and receiving a pacemaker, he fought his way back into the Lille side, became captain, and produced one of the best seasons of his career. \"He never let go. He believed in himself, and he believed in the people who looked after him,\" said Lille coach Bruno Genesio."}, special: "Comeback kid" },
  { number: 22, name: 'Ibrahim Maza', position: 'MF', age: 20, club: 'Bayer Leverkusen', bio: {"es":"Con sólo 20 años, Maza claramente está avanzando. Tiene un gran talento ofensivo y se destaca por desplazarse hacia espacios espaciosos y recibir el balón en la media vuelta. Su bajo centro de gravedad y su poderosa parte inferior del cuerpo le permiten afrontar desafíos y mostrar la calidad técnica que lo distingue, con pases incisivos y regates intrépidos. Desde que llegó al Bayer Leverkusen ha recibido muchas comparaciones con Florian Wirtz. No es que esté contento con eso. \"No me gusta que me comparen así\", dijo Maza al sitio web del club. \"Se convirtió en el fichaje más caro de la Premier League y espero poder estar a su nivel algún día, pero todavía no he llegado a ese punto\". Nacido en Berlín, jugó con Alemania hasta la categoría sub-20 antes de declararse con Argelia el año pasado. Fue una decisión calculada. \"Es puramente por razones deportivas, porque se alinea mejor con mi futuro futbolístico\", dijo. \"En la selección alemana, la competencia por mi puesto es extremadamente feroz, por lo que es difícil entrar en el once inicial o encontrar un espacio en ese equipo. Desde una perspectiva deportiva, representar a Argelia me da una mayor oportunidad de jugar en la Copa del Mundo y competir al más alto nivel. Por eso tomé esta decisión con plena confianza\".","en":"Aged just 20, Maza is clearly going places. A fine attacking talent, he excels at drifting into pockets of space, receiving the ball on the half-turn. His low centre of gravity and powerful lower body allow him to ride challenges and show off the technical quality that sets him apart, with incisive passes and fearless dribbles. Since arriving at Bayer Leverkusen he has drawn plenty of comparisons to Florian Wirtz. Not that he is pleased about it. “I don’t like being compared like that,” Maza told the club’s website. “He became the most expensive signing in the Premier League, and I hope I can be at his level someday, but I’m not there yet.” Born in Berlin, he played for Germany up to Under-20 level before declaring for Algeria last year. It was a calculated decision. “It’s purely for sporting reasons, because it aligns better with my footballing future,” he said. “In the German national team, the competition for my position is extremely fierce, so it's tough to break into the starting eleven or find space in that squad. From a sporting perspective, representing Algeria gives me a greater chance to play in the World Cup and compete at the highest level. That's why I made this decision with full confidence.\""}, special: "One to watch" },
  { number: 24, name: 'Yacine Titraoui', position: 'MF', age: 0, club: 'Royal Charleroi', bio: {"es":"“El Verratti argelino” es como suelen ver a Titraoui los aficionados norteafricanos. Ningún jugador argelino es mejor sentado frente a la defensa y dictando el juego con pases precisos y progresivos que el centrocampista del Charleroi. Su tasa de pases completados ronda el 85% y se destaca en leer el juego y realizar intercepciones oportunas. Sin embargo, otro rasgo que comparte con Verratti es la tendencia a recibir reservas. Después de dos temporadas completas con Charleroi, espera que una actuación positiva en la Copa del Mundo este verano pueda asegurarle el pase a una de las ligas de élite de Europa. En los meses previos al torneo estuvo vinculado con varios clubes de Inglaterra, incluidos Leeds, Sunderland y Wolves.","en":"“The Algerian Verratti” is how Titraoui is often seen by North African fans. No Algerian player is better at sitting in front of the defence and dictating play with precise, progressive passing than the Charleroi midfielder. His pass completion rate hovers around 85%, and he excels at reading the game and making timely interceptions. Another trait he shares with Verratti, though, is a tendency to pick up bookings. After two full seasons with Charleroi, he will be hoping that a positive World Cup showing this summer could secure a move to one of Europe’s elite leagues. In the months before the tournament he was linked with several clubs in England including Leeds, Sunderland and Wolves."}, special: "‘The Algerian Verratti’" },
  // Delanteros
  { number: 7, name: 'Riyad Mahrez', position: 'FW', age: 35, club: 'Al-Ahli', bio: {"es":"Muy pocos futbolistas pueden igualar lo que ha conseguido Mahrez en el juego. Entre sus elogios, el capitán de Argelia cuenta con cinco títulos de la Premier League, una medalla de ganador de la Liga de Campeones, dos Copas FA, tres Copas de la Liga, premios al jugador del año de la PFA y la CAF, y muchos otros honores individuales y de clubes. La única mancha en su carrera para los fanáticos de Argelia es la falta de una actuación estelar en una Copa del Mundo. En 2014, su única aparición fue en la derrota por 2-1 ante Bélgica, donde registró 37 toques, fue desposeído tres veces y fue sustituido en el minuto 71. No volvió a aparecer cuando Argelia avanzó a octavos de final. Ahora, con 35 años y acercándose al ocaso de su carrera, está decidido a llevar a Argelia a los cuartos de final de una Copa del Mundo por primera vez. Un logro así elevaría su estatus en la tradición del fútbol africano. Aún así, algunos fanáticos argumentan que ya no tiene las piernas para justificar un puesto titular en Argelia, y que tal vez ya sea hora de pasar el testigo a talentos en ascenso como Anis Hadj Moussa, del Feyenoord.","en":"Very few footballers can match what Mahrez has achieved in the game. Among his accolades, the Algeria captain boasts five Premier League titles, a Champions League winner’s medal, two FA Cups, three League Cups, PFA and CAF player of the year awards, and many other individual and club honours. The only blemish on his career for Algeria fans is that lack of a stellar display at a World Cup. In 2014 his only appearance came in a 2-1 defeat to Belgium where he registered 37 touches, was dispossessed three times and was substituted in the 71st minute. He did not feature again as Algeria surged to the Last 16. Now aged 35 and nearing the twilight of his career, he is determined to lead Algeria into the quarter-finals of the World Cup for the very first time. Such an achievement would elevate his status in African footballing lore. Still, some fans argue that he no longer has the legs to justify a starting place for Algeria, and that it may already be time to hand the mantle to rising talents such as Feyenoord’s Anis Hadj Moussa."}, special: "National talisman" },
  { number: 9, name: 'Amine Gouiri', position: 'FW', age: 26, club: 'Marseille', bio: {"es":"Muchos jugadores del Lyon han sido apodados “el próximo Karim Benzema” desde que el ex ganador del Balón de Oro saltó a la fama a mediados de la década de 2000. Si bien es comprensible que todos se hayan quedado cortos, Gouiri es quizás el que más se parece estilísticamente a Benzema. \"A Karim le gusta participar en el juego, creando ocasiones y marcando goles\", dijo Gouiri a Fifa.com. \"Aunque las estadísticas son increíblemente importantes para un delantero centro hoy en día, lo que me encanta es ser parte del juego. Combinar ambas cosas es fantástico\". Con Argelia lo hace con buenos resultados, normalmente comenzando el partido como objetivo antes de cambiar de posición con su compañero Mohamed Amoura en el ala izquierda. Desde un punto de vista técnico tiene muy pocas debilidades, rara vez pierde un pase o falla un tiro. Sin embargo, a veces tiene tendencia a dejar pasar el juego. Necesitará aumentar su número de toques de balón si el ataque de Argelia quiere hacer funcionar todos los cilindros en América del Norte.","en":"Plenty of Lyon players have been dubbed “the next Karim Benzema” since the former Ballon d'Or winner rose to prominence in the mid-2000s. While all have understandably fallen short, Gouiri is perhaps the one who most closely resembles Benzema stylistically. “Karim likes to be involved in the game, by both creating chances and scoring goals,” Gouiri told Fifa.com. “Even though stats are incredibly important for a centre-forward these days, what I love is being part of the game. Combining the two is great.” With Algeria he does that to solid effect, typically starting the match as a target man before switching positions with his teammate Mohamed Amoura on the left wing. From a technical standpoint he has very few weaknesses, rarely misplacing a pass or shanking a shot. However, he does have a tendency to, at times, let the game pass him by. He will need to increase his number of touches on the ball if Algeria’s attack is to click on all cylinders in North America."} },
  { number: 11, name: 'Anis Hadj Moussa', position: 'FW', age: 23, club: 'Feyenoord', bio: {"es":"El regateador más emocionante del equipo, y ese no es un título fácil de reclamar. Originario de París, Hadj Moussa se unió al Feyenoord en 2024 y ha tenido un gran impacto, convirtiéndose en vicecapitán y uno de los talentos más destacados de la Eredivisie, liderando regularmente las clasificaciones de regate y, bajo la dirección de Robin van Persie, mejorando enormemente su producto final. \"Es interesante ver cómo se está desarrollando\", dijo recientemente el exdelantero del Arsenal. \"No creo que ocupe el lugar de Riyad Mahrez con Argelia porque es un jugador tremendo, pero Mahrez ha insinuado que se retirará después del Mundial, lo que dejaría libre el lugar para Hadj Moussa\". Si bien Van Persie probablemente tenga razón en que Mahrez se mantiene a la cabeza en el orden jerárquico, aún se espera que Hadj Moussa juegue minutos importantes, a menudo cuando las envejecidas piernas de Mahrez comienzan a desvanecerse alrededor de la hora. Es otro jugador vinculado con un posible traslado a Inglaterra este verano.","en":"The most exciting dribbler in the side, and that isn’t an easy title to claim. A Paris native, Hadj Moussa joined Feyenoord in 2024 and has made a huge impact, becoming vice-captain and one of the Eredivisie’s most outstanding talents, regularly leading the dribbling rankings and, under Robin van Persie, hugely improving his end product. “It’s interesting to see how he is developing,” the former Arsenal striker said recently. “I don’t think he’ll take Riyad Mahrez’s place for Algeria because he’s a tremendous player, but Mahrez has hinted that he’ll retire after the World Cup, which would free up the spot for Hadj Moussa.” While Van Persie is probably right that Mahrez stays ahead in the pecking order, Hadj Moussa is still expected to play significant minutes, often coming on when Mahrez’s ageing legs begin to fade around the hour mark. He is another player linked with a possible move to England this summer."}, special: "Dribbling king" },
  { number: 12, name: 'Nadhir Benbouali', position: 'FW', age: 0, club: 'Eto FC', bio: {"es":"Benbouali ha sentido muchas veces que el mundo del fútbol no ha sido justo con él. Cuando era adolescente, el ASO Chlef de su ciudad natal no le ofreció un contrato profesional, a pesar de haber marcado más de 30 goles en las ligas juveniles y de que su padre trabajaba como médico en la selección absoluta. \"Nunca entendí por qué\", dijo al medio argelino El Heddaf. \"Sin embargo, todo en la vida sucede por una razón y tuve la suerte de firmar con la mejor academia de Argelia, Paradou AC\". En Paradou, Benbouali se convirtió en uno de los delanteros más prolíficos de la liga argelina, pero la convocatoria a la selección nacional seguía siendo difícil de alcanzar. Fue sólo hace unos meses, después de terminar tercero en la tabla de goleadores de la liga húngara y ayudar al ETO FC a conseguir el título de liga, que finalmente obtuvo su recompensa. Benbouali es el único verdadero objetivo de Argelia, un delantero físicamente imponente que destaca en los duelos aéreos y ofrece una dimensión diferente en ataque. Incluso si no es titular, es probable que desempeñe un papel durante la Copa del Mundo.","en":"Benbouali has often felt that the footballing world has not been fair to him. As a teenager, he was not offered a professional contract by his hometown club ASO Chlef, despite scoring more than 30 goals in the youth leagues and despite his father working as a doctor for the senior team. \"I never understood why,\" he told Algerian outlet El Heddaf. \"Yet, everything in life happens for a reason and I was lucky enough to sign with the best academy in Algeria, Paradou AC.\" At Paradou, Benbouali developed into one of the Algerian league's most prolific strikers, but a call-up to the national team remained elusive. It was only a few months ago, after finishing third in the Hungarian league's scoring charts and helping ETO FC secure the league title, that he finally earned his reward. Benbouali is Algeria's only true target man, a physically imposing striker who excels in aerial duels and offers a different dimension in attack. Even if he does not start, he is likely to play a role during the World Cup."} },
  { number: 18, name: 'Mohamed Amine Amoura', position: 'FW', age: 25, club: 'Wolfsburg', bio: {"es":"Amoura, de 19 años, tardó sólo unos minutos en anunciarse en su debut absoluto con el ES Setif, anotando dos goles en el derbi contra su archirrival CA Bordj Bou Arreridj. El doblete marcó la pauta para una carrera definida por la explosividad. Desde ES Sétif hasta Lugano, pasando por el Royale Union Saint-Gilloise y ahora en Wolfsburg, constantemente se ha enfrentado a nuevos desafíos, ya sea desplegado en la banda izquierda o como un falso nueve, y su aceleración y franqueza lo convierten en una amenaza constante. Durante las eliminatorias para la Copa del Mundo, Amoura lideró la tabla de goleadores africanos con 10 goles y ahora es ampliamente considerado como el arma de ataque más decisiva de Argelia. Sin embargo, en febrero apareció en los titulares negativos cuando se burló de un seguidor congoleño conocido por pasar los partidos de la Copa Africana de Naciones de pie con el brazo derecho levantado al estilo de una famosa estatua del venerado primer líder del país, Patrice Lumumba. Amoura, que imitó al aficionado y luego cayó al suelo como si la estatua hubiera sido derribada, se disculpó más tarde en línea: \"No era consciente de lo que representaba la persona o el símbolo en las gradas. Simplemente quería bromear, de buen humor, sin ninguna mala intención ni deseo de provocar a nadie\".","en":"It took a 19-year-old Amoura just a few minutes to announce himself in his senior debut for ES Setif, scoring twice in the derby against arch-rivals CA Bordj Bou Arreridj. The double set the tone for a career defined by explosiveness. From ES Setif to Lugano to Royale Union Saint-Gilloise and now at Wolfsburg, he has consistently risen to new challenges whether deployed on the left wing or as a false nine, with his acceleration and directness making him a constant threat. During the World Cup qualifiers Amoura led the African scoring charts with 10 goals and is now widely regarded as Algeria’s most decisive attacking weapon. In February, though, he made negative headlines when he mocked a Congolese supporter known for spending matches at the Africa Cup of Nations standing still with his right arm raised in the style of a famous statue of the country’s revered first leader Patrice Lumumba. Amoura, who mimicked the fan then fell to the ground as though the statue had been toppled, later apologised online: \"I wasn't aware of what the person or symbol in the stands represented. I simply wanted to joke around, in a good-natured way, without any ill intent or desire to provoke anyone.”"}, special: "Main goalscorer" },
  { number: 20, name: 'Adil Boulbina', position: 'FW', age: 23, club: 'Al-Duhail', bio: {"es":"Es un recién llegado internacional, pero Boulbina ya tiene un momento destacado con Argelia en su currículum. En su primera aparición en la Copa Africana de Naciones del año pasado, entrando como suplente contra la República Democrática del Congo, marcó un gol impresionante al final de la prórroga para enviar a Argelia a los cuartos de final. Se formó en la famosa Academia Paradou, considerada una de las mejores de África, y terminó la temporada 2024-25 como máximo goleador de la Ligue Professionnelle 1 de Argelia con 20 goles. Esa forma le valió un traspaso muy lucrativo al Al-Duhail, donde se reunió con el ex seleccionador de Argelia, Djamel Belmadi. Es poco probable que sea titular este verano, pero su franqueza y su capacidad para cambiar de juego lo convierten en una opción valiosa desde el banquillo.","en":"He’s an international newcomer, but Boulbina already has one stand-out moment for Algeria on his CV. In his first outing at last year’s Africa Cup of Nations, coming on as a sub against DR Congo, he scored a stunning goal late in extra-time to send Algeria through to the quarter-finals. He was trained in the famed Paradou Academy, widely regarded as one of the best in Africa, and finished the 2024-25 season as the top scorer in the Algerian Ligue Professionnelle 1 with 20 goals. That form earned him a big-money move to Al-Duhail, where he reunited with former Algeria coach Djamel Belmadi. He is unlikely to start this summer, but his directness and ability to change games make him a valuable option off the bench."} },
  { number: 25, name: 'Farès Ghedjemis', position: 'FW', age: 24, club: 'Frosinone', bio: {"es":"Ghedjemis disfrutó de una gran campaña esta temporada, anotando 15 goles en 37 partidos desde la banda mientras ayudó al Frosinone a asegurar el ascenso a la Serie A después de una ausencia de tres años. Se le considera uno de los jugadores más destacados de la Serie B y ha generado un entusiasmo considerable entre los aficionados de cara a la próxima temporada. A primera vista, Ghedjemis parece encajar en un molde familiar para Argelia. Extremo zurdo nacido en los suburbios de París que juega principalmente en la banda derecha, pertenece a una generación fuertemente influenciada por el estilo de juego de Riyad Mahrez. Sin embargo, hay una diferencia clave. A diferencia de los muchos extremos argelinos talentosos que prefieren recibir el balón en los pies, Ghedjemis busca constantemente correr detrás de las defensas rivales. Presumiblemente, ese atributo fue lo que convenció a Petkovic de seleccionarlo por delante de otros jugadores creativos como Ilan Kebbal, Badredine Bouanani y Mohamed Bachir Belloumi.","en":"Ghedjemis enjoyed a breakthrough campaign this season, scoring 15 goals in 37 matches from the wing as he helped Frosinone secure promotion back to Serie A after a three-year absence. He is regarded as one of the standout players in Serie B and has generated considerable excitement among supporters ahead of next season. At first glance, Ghedjemis appears to fit a familiar mould for Algeria. A left-footed winger born in the suburbs of Paris who operates primarily on the right flank, he belongs to a generation heavily influenced by Riyad Mahrez's style of play. However, there is one key difference. Unlike the many gifted Algerian wingers who prefer receiving the ball to their feet, Ghedjemis is constantly looking to make runs in behind opposition defences. That attribute is presumably what convinced Petkovic to select him ahead of other creative wide players such as Ilan Kebbal, Badredine Bouanani and Mohamed Bachir Belloumi."} },
];

export const lineup = {
  formation: '4-3-3',
  startingXI: [23, 17, 2, 18, 15, 10, 6, 8, 7, 11, 9]
};
